'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),cp=require('node:child_process');
const repo=path.resolve(__dirname,'..'),root=path.join(repo,'decompilation-repair-2026-11-01'),work='D:/Codex-iflytek-decompilation-repair-20261101',old='D:/Codex-iflytek-apk-analysis-20261101',hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function main(){const catalog=JSON.parse(fs.readFileSync(path.join(root,'overlay-catalog.json'))),pairs=new Map();
 for(const v of catalog.versions)for(const c of v.components)if(c.overlay){const bytes=fs.readFileSync(path.join(root,c.overlay.path));if(hash(bytes)!==c.overlay.sha256||bytes.length!==c.overlay.bytes)throw Error('Overlay changed');const overlay=JSON.parse(bytes);for(const r of overlay.replacements){const key=r.before.sha256+'\0'+r.after.sha256;if(!pairs.has(key))pairs.set(key,{...r,group:c.dexSetSha256,appliesTo:[]});pairs.get(key).appliesTo.push({variant:v.variant,dexSetSha256:c.dexSetSha256,descriptors:r.methods.map(m=>m.descriptor)});}}
 const rows=[];fs.mkdirSync(path.join(root,'patches'),{recursive:true});for(const r of pairs.values()){const before=path.join(old,'jadx-output',r.group,r.path),after=path.join(work,r.after.cas);for(const [file,record] of [[before,r.before],[after,r.after]]){const b=fs.readFileSync(file);if(hash(b)!==record.sha256||b.length!==record.bytes)throw Error('Diff input differs');}const result=cp.spawnSync('git',['-c','core.autocrlf=false','diff','--no-index','--no-ext-diff','--no-textconv','--text','--',before,after],{cwd:repo,encoding:'utf8',windowsHide:true,maxBuffer:16*1024*1024});if(result.status!==1||result.error)throw Error('Expected exact two-file textual diff');const start=result.stdout.indexOf('@@ ');if(start<0)throw Error('Missing unified hunk');const patch='--- baseline/'+r.path+'\n+++ reviewed/'+r.path+'\n'+result.stdout.slice(start),file='patches/'+r.after.sha256+'.patch';fs.writeFileSync(path.join(root,file),patch);rows.push({file,sha256:hash(patch),bytes:Buffer.byteLength(patch),logicalPath:r.path,before:r.before,after:r.after,appliesTo:r.appliesTo});}
 const report={schemaVersion:1,scope:'Human-review diffs. Canonical byte-exact materialization uses approved CAS and PATH-MAP, not text patch application.',uniquePatches:rows.length,methodInstances:rows.reduce((n,r)=>n+r.appliesTo.length,0),patches:rows};fs.writeFileSync(path.join(root,'patches/index.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({uniquePatches:rows.length,methodInstances:report.methodInstances}));}
if(require.main===module)main();
